const palacePath = '/Volumes/T7/claude-palace-out/palace-index.md';
let palaceStatus;
try {
  if (fs.existsSync(palacePath)) {
    const age = Math.floor((Date.now() - fs.statSync(palacePath).mtimeMs) / 86400000);
