// Oracle SSE stream — pipes local LLM output as it arrives, no blocking wait
router.get('/oracle/stream', async (req, res) => {
    const command = String(req.query.command || '').trim();
    const modelId = String(req.query.model || 'qwen-liberated:latest');
    if (!command) { res.status(400).json({ error: 'command required' }); return; }

    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders();

    const send = (event: string, data: unknown) => {
        res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
    };

    send('start', { model: modelId, command });

    try {
        const ollamaBase = process.env.OLLAMA_BASE_URL || 'http://localhost:11434';
        const fetch = (await import('node-fetch')).default;
        const upstream = await fetch(`${ollamaBase}/api/chat`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                model: modelId,
                messages: [{ role: 'user', content: command }],
                stream: true
            }),
            signal: (req as any).signal
        });

        if (!upstream.ok) throw new Error(`Ollama HTTP ${upstream.status}`);
        if (!upstream.body) throw new Error('No response body');

        let full = '';
        for await (const chunk of upstream.body as any) {
            const text = chunk.toString();
            for (const line of text.split('\n').filter(Boolean)) {
                try {
                    const parsed = JSON.parse(line);
                    const token = parsed?.message?.content || '';
                    if (token) {
                        full += token;
                        send('token', { token });
                    }
                    if (parsed?.done) {
                        send('done', { content: full, model: modelId });
                        res.end();
                        return;
                    }
                } catch (_) {}
            }
        }
        send('done', { content: full, model: modelId });
    } catch (err: any) {
        send('error', { message: err.message || 'STREAM_FAILED' });
    }
    res.end();
});

