import React, { useCallback, useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    submitOracleCommandStream,
    submitOracleCommand,
    subscribeOracleCommandState,
    type OracleCommandState
} from '../../lib/oracleCommandBridge';
import { apiFetch } from '../../lib/runtime';
import VisualSynthesisLane from './VisualSynthesisLane';
import OracleToolOrbs from './OracleToolOrbs';
import OracleTerminal from './OracleTerminal';

interface ChatMessage {
    id: string;
    role: 'user' | 'nexus';
    content: string;
    streaming?: boolean;
    timestamp: string;
    files?: UploadedFile[];
}

interface UploadedFile {
    name: string;
    type: string;
    dataUrl: string;
    size: number;
}

interface ImageModel {
    id: string;
    label: string;
    provider: string;
}

type TabId = 'context' | 'research' | 'code' | 'visual' | 'ops';

const TABS: { id: TabId; label: string; icon: string }[] = [
    { id: 'context', label: 'Context',  icon: '◈' },
    { id: 'research', label: 'Research', icon: '◎' },
    { id: 'code',    label: 'Code',     icon: '⬡' },
    { id: 'visual',  label: 'Visual',   icon: '◆' },
    { id: 'ops',     label: 'Ops',      icon: '◉' }
];

const REASONING_LEVELS = ['low', 'medium', 'high', 'council'] as const;
type ReasoningLevel = typeof REASONING_LEVELS[number];

const REASONING_COLORS: Record<ReasoningLevel, string> = {
    low:     'var(--text-dim)',
    medium:  'var(--cyan-glow)',
    high:    'var(--gold-solar)',
    council: 'var(--red-fusion)'
};

export default function OraclePage() {
    const [messages, setMessages] = useState<ChatMessage[]>([{
        id: 'boot',
        role: 'nexus',
        content: 'NEXUS — Oracle online. All systems nominal. What directive shall I process?',
        timestamp: new Date().toISOString()
    }]);
    const [input, setInput]           = useState('');
    const [activeTab, setActiveTab]   = useState<TabId>('context');
    const [reasoning, setReasoning]   = useState<ReasoningLevel>('medium');
    const [terminalOpen, setTerminalOpen] = useState(false);
    const [dragOver, setDragOver]     = useState(false);
    const [pendingFiles, setPendingFiles] = useState<UploadedFile[]>([]);
    const [isListening, setIsListening] = useState(false);
    const [imageModels, setImageModels] = useState<{ kie: ImageModel[]; remote: ImageModel[] }>({ kie: [], remote: [] });
    const [oracleState, setOracleState] = useState<OracleCommandState | null>(null);
    const [models, setModels]          = useState<any[]>([]);
    const [selectedModel, setSelectedModel] = useState<string>('qwen-liberated:latest');

    const chatEndRef   = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const recognitionRef = useRef<SpeechRecognition | null>(null);

    // Subscribe to oracle state
    useEffect(() => {
        return subscribeOracleCommandState(setOracleState);
    }, []);

    // Auto-scroll chat
    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    // Load models + image model catalog
    useEffect(() => {
        apiFetch('/api/neural/models').then(r => r.json()).then(setModels).catch(() => {});
        apiFetch('/api/neural/images/models').then(r => r.json()).then(setImageModels).catch(() => {});
    }, []);

    const addMessage = useCallback((msg: ChatMessage) => {
        setMessages(prev => [...prev, msg]);
    }, []);

    const updateLastNexus = useCallback((patch: Partial<ChatMessage>) => {
        setMessages(prev => {
            const idx = [...prev].reverse().findIndex(m => m.role === 'nexus');
            if (idx === -1) return prev;
            const realIdx = prev.length - 1 - idx;
            return prev.map((m, i) => i === realIdx ? { ...m, ...patch } : m);
        });
    }, []);

    const handleSubmit = useCallback(async () => {
        const cmd = input.trim();
        if (!cmd && pendingFiles.length === 0) return;
        setInput('');

        const userMsg: ChatMessage = {
            id: `u-${Date.now()}`,
            role: 'user',
            content: cmd || '[file upload]',
            timestamp: new Date().toISOString(),
            files: pendingFiles.length > 0 ? [...pendingFiles] : undefined
        };
        addMessage(userMsg);
        setPendingFiles([]);

        const nexusId = `n-${Date.now()}`;
        addMessage({ id: nexusId, role: 'nexus', content: '', streaming: true, timestamp: new Date().toISOString() });

        const useCouncil = reasoning === 'council';

        if (!useCouncil) {
            // Streaming path — near-realtime
            try {
                await submitOracleCommandStream({
                    command: cmd || 'describe uploaded files',
                    source: 'typed',
                    modelId: selectedModel,
                    onChunk: (chunk) => {
                        if (chunk.type === 'token') {
                            setMessages(prev => prev.map(m =>
                                m.id === nexusId
                                    ? { ...m, content: m.content + (chunk.token || ''), streaming: true }
                                    : m
                            ));
                        } else if (chunk.type === 'done') {
                            setMessages(prev => prev.map(m =>
                                m.id === nexusId
                                    ? { ...m, content: chunk.content || m.content, streaming: false }
                                    : m
                            ));
                        } else if (chunk.type === 'error') {
                            setMessages(prev => prev.map(m =>
                                m.id === nexusId
                                    ? { ...m, content: `[Oracle error: ${chunk.error}]`, streaming: false }
                                    : m
                            ));
                        }
                    }
                });
            } catch (err: any) {
                updateLastNexus({ content: `[Stream failed: ${err.message}]`, streaming: false });
            }
        } else {
            // Council mode — blocking with phase display
            try {
                const result = await submitOracleCommand({
                    command: cmd,
                    source: 'typed',
                    useCouncil: true
                });
                const content = result?.response || result?.content || JSON.stringify(result);
                updateLastNexus({ content: String(content), streaming: false });
            } catch (err: any) {
                updateLastNexus({ content: `[Council error: ${err.message}]`, streaming: false });
            }
        }
    }, [input, pendingFiles, reasoning, selectedModel, addMessage, updateLastNexus]);

    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmit(); }
    }, [handleSubmit]);

    const handleFileDrop = useCallback((files: FileList | null) => {
        if (!files) return;
        const allowed = ['application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp',
            'text/markdown', 'text/plain', 'application/x-python', 'text/x-python'];
        Array.from(files).forEach(file => {
            if (!allowed.some(t => file.type === t || file.name.endsWith('.md') || file.name.endsWith('.py') || file.name.endsWith('.ts'))) return;
            const reader = new FileReader();
            reader.onload = () => {
                setPendingFiles(prev => [...prev, {
                    name: file.name,
                    type: file.type,
                    dataUrl: reader.result as string,
                    size: file.size
                }]);
            };
            reader.readAsDataURL(file);
        });
    }, []);

    const toggleVoice = useCallback(() => {
        const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SR) return;
        if (isListening) {
            recognitionRef.current?.stop();
            setIsListening(false);
            return;
        }
        const rec = new SR();
        rec.lang = 'en-US';
        rec.continuous = false;
        rec.onresult = (e: SpeechRecognitionEvent) => {
            const text = e.results[0]?.[0]?.transcript || '';
            setInput(prev => (prev + ' ' + text).trim());
            setIsListening(false);
        };
        rec.onend = () => setIsListening(false);
        rec.start();
        recognitionRef.current = rec;
        setIsListening(true);
    }, [isListening]);

    const cycleReasoning = useCallback(() => {
        setReasoning(prev => {
            const idx = REASONING_LEVELS.indexOf(prev);
            return REASONING_LEVELS[(idx + 1) % REASONING_LEVELS.length];
        });
    }, []);

    const isBusy = oracleState?.phase === 'submitted' || oracleState?.phase === 'deliberating';

    return (
        <div className="oracle-page" onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={e => { e.preventDefault(); setDragOver(false); handleFileDrop(e.dataTransfer.files); }}
        >
            {/* Drop overlay */}
            <AnimatePresence>
                {dragOver && (
                    <motion.div className="oracle-drop-overlay"
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                        <span>Drop files into NEXUS</span>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Main layout */}
            <div className="oracle-layout">

                {/* LEFT — Category tabs */}
                <div className="oracle-tabs">
                    {TABS.map(tab => (
                        <button key={tab.id} className={`oracle-tab ${activeTab === tab.id ? 'active' : ''}`}
                            onClick={() => setActiveTab(tab.id)}>
                            <span className="tab-icon">{tab.icon}</span>
                            <span className="tab-label">{tab.label}</span>
                        </button>
                    ))}
                    <div className="oracle-tab-spacer"/>
                    <button className="oracle-tab terminal-toggle" onClick={() => setTerminalOpen(p => !p)}>
                        <span className="tab-icon">_</span>
                        <span className="tab-label">Terminal</span>
                    </button>
                </div>

                {/* CENTER — Chat + orbs */}
                <div className="oracle-center">

                    {/* Tool orbs or tab content */}
                    <div className="oracle-content-area">
                        {activeTab === 'visual' ? (
                            <VisualSynthesisLane models={imageModels} />
                        ) : (
                            <OracleToolOrbs activeTab={activeTab} />
                        )}
                    </div>

                    {/* Chat thread */}
                    <div className="oracle-chat">
                        <div className="oracle-messages">
                            {messages.map(msg => (
                                <motion.div key={msg.id} className={`oracle-msg oracle-msg--${msg.role}`}
                                    initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
                                    transition={{ duration: 0.2 }}>
                                    <span className="msg-label">
                                        {msg.role === 'user' ? 'NEXUS' : 'ORACLE'}
                                    </span>
                                    <div className="msg-body">
                                        {msg.content}
                                        {msg.streaming && <span className="cursor-blink">▋</span>}
                                    </div>
                                    {msg.files && msg.files.length > 0 && (
                                        <div className="msg-files">
                                            {msg.files.map((f, i) => (
                                                <span key={i} className="msg-file-pill">{f.name}</span>
                                            ))}
                                        </div>
                                    )}
                                </motion.div>
                            ))}
                            {isBusy && (
                                <div className="oracle-phase-indicator">
                                    <span className="phase-dot"/>
                                    {oracleState?.phase} · {oracleState?.elapsedMs ? Math.floor(oracleState.elapsedMs / 1000) + 's' : '...'}
                                </div>
                            )}
                            <div ref={chatEndRef}/>
                        </div>

                        {/* Pending file pills */}
                        {pendingFiles.length > 0 && (
                            <div className="oracle-pending-files">
                                {pendingFiles.map((f, i) => (
                                    <span key={i} className="pending-file-pill">
                                        {f.name}
                                        <button onClick={() => setPendingFiles(p => p.filter((_, j) => j !== i))}>×</button>
                                    </span>
                                ))}
                            </div>
                        )}

                        {/* Input bar */}
                        <div className="oracle-input-bar">
                            {/* Plus — file picker */}
                            <button className="input-action input-plus" onClick={() => fileInputRef.current?.click()} title="Attach file">
                                +
                            </button>
                            <input ref={fileInputRef} type="file" multiple hidden
                                accept=".pdf,.png,.jpg,.jpeg,.gif,.webp,.md,.py,.ts,.txt"
                                onChange={e => handleFileDrop(e.target.files)}/>

                            <textarea
                                className="oracle-textarea"
                                value={input}
                                onChange={e => setInput(e.target.value)}
                                onKeyDown={handleKeyDown}
                                placeholder="Ask NEXUS..."
                                rows={1}
                            />

                            {/* Model selector */}
                            <select className="oracle-model-select" value={selectedModel}
                                onChange={e => setSelectedModel(e.target.value)}>
                                {models.length > 0
                                    ? models.map((m: any) => <option key={m.id} value={m.id}>{m.name || m.id}</option>)
                                    : <option value="qwen-liberated:latest">Qwen Local</option>}
                            </select>

                            {/* Reasoning level */}
                            <button className="input-action reasoning-level"
                                style={{ color: REASONING_COLORS[reasoning] }}
                                onClick={cycleReasoning}
                                title={`Reasoning: ${reasoning}`}>
                                {reasoning.slice(0, 3).toUpperCase()}
                            </button>

                            {/* Mic */}
                            <button className={`input-action input-mic ${isListening ? 'active' : ''}`}
                                onClick={toggleVoice} title="Voice input">
                                {isListening ? '◉' : '🎤'}
                            </button>

                            {/* Send */}
                            <button className="input-action input-send" onClick={handleSubmit} disabled={isBusy}>
                                {isBusy ? '⟳' : '↑'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Terminal pane (collapsible) */}
            <AnimatePresence>
                {terminalOpen && (
                    <motion.div className="oracle-terminal-pane"
                        initial={{ height: 0 }} animate={{ height: 320 }} exit={{ height: 0 }}
                        transition={{ duration: 0.25 }}>
                        <OracleTerminal />
                    </motion.div>
                )}
            </AnimatePresence>

            <style>{ORACLE_STYLES}</style>
        </div>
    );
}

const ORACLE_STYLES = `
.oracle-page {
  display: flex;
  flex-direction: column;
  height: 100%;
  background: var(--bg-void);
  color: var(--silver-albedo);
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
  position: relative;
  overflow: hidden;
}

.oracle-drop-overlay {
  position: absolute;
  inset: 0;
  background: rgba(159,232,115,0.08);
  border: 2px dashed var(--cyan-glow);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  color: var(--cyan-glow);
  letter-spacing: 0.12em;
}

.oracle-layout {
  display: flex;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

/* LEFT TABS */
.oracle-tabs {
  display: flex;
  flex-direction: column;
  width: 88px;
  border-right: 1px solid rgba(159,232,115,0.12);
  padding: 8px 0;
  gap: 2px;
  flex-shrink: 0;
}

.oracle-tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 4px;
  background: none;
  border: none;
  color: var(--text-dim);
  cursor: pointer;
  font-family: inherit;
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-left: 2px solid transparent;
  transition: all 0.15s;
}
.oracle-tab:hover { color: var(--cyan-glow); background: rgba(159,232,115,0.04); }
.oracle-tab.active {
  color: var(--cyan-glow);
  border-left-color: var(--cyan-glow);
  background: rgba(159,232,115,0.06);
}
.oracle-tab.terminal-toggle { color: var(--gold-solar); margin-top: auto; }
.tab-icon { font-size: 14px; }
.oracle-tab-spacer { flex: 1; }

/* CENTER */
.oracle-center {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-width: 0;
}

.oracle-content-area {
  flex: 0 0 260px;
  border-bottom: 1px solid rgba(159,232,115,0.1);
  overflow-y: auto;
  padding: 12px;
}

/* CHAT */
.oracle-chat {
  display: flex;
  flex-direction: column;
  flex: 1;
  overflow: hidden;
  min-height: 0;
}

.oracle-messages {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.oracle-msg { display: flex; flex-direction: column; gap: 3px; max-width: 90%; }
.oracle-msg--user { align-self: flex-end; }
.oracle-msg--nexus { align-self: flex-start; }

.msg-label {
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.45;
}
.oracle-msg--user .msg-label  { color: var(--cyan-glow); text-align: right; }
.oracle-msg--nexus .msg-label { color: var(--gold-solar); }

.msg-body {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(159,232,115,0.1);
  border-radius: 2px;
  padding: 8px 12px;
  font-size: 13px;
  line-height: 1.6;
  white-space: pre-wrap;
  word-break: break-word;
}
.oracle-msg--user .msg-body {
  background: rgba(159,232,115,0.06);
  border-color: rgba(159,232,115,0.2);
}

.cursor-blink {
  animation: blink 0.8s step-end infinite;
  color: var(--cyan-glow);
}
@keyframes blink { 50% { opacity: 0; } }

.msg-files { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 4px; }
.msg-file-pill {
  font-size: 10px;
  padding: 2px 8px;
  background: rgba(159,232,115,0.1);
  border: 1px solid rgba(159,232,115,0.2);
  border-radius: 2px;
  color: var(--cyan-glow);
}

.oracle-phase-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--gold-solar);
  opacity: 0.7;
  padding: 0 4px;
}
.phase-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: var(--gold-solar);
  animation: pulseDot 1s ease-in-out infinite;
}
@keyframes pulseDot { 0%,100% { opacity: 1; } 50% { opacity: 0.3; } }

/* PENDING FILES */
.oracle-pending-files {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 6px 16px;
  border-top: 1px solid rgba(159,232,115,0.08);
}
.pending-file-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  padding: 3px 8px;
  background: rgba(118,185,0,0.1);
  border: 1px solid rgba(118,185,0,0.3);
  border-radius: 2px;
  color: var(--gold-solar);
}
.pending-file-pill button {
  background: none; border: none; color: var(--red-fusion);
  cursor: pointer; font-size: 13px; padding: 0; line-height: 1;
}

/* INPUT BAR */
.oracle-input-bar {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 10px 16px;
  border-top: 1px solid rgba(159,232,115,0.12);
  background: rgba(8,8,8,0.6);
}

.oracle-textarea {
  flex: 1;
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(159,232,115,0.15);
  border-radius: 2px;
  color: var(--silver-albedo);
  font-family: inherit;
  font-size: 13px;
  padding: 8px 10px;
  resize: none;
  outline: none;
  min-height: 36px;
  max-height: 120px;
  line-height: 1.5;
  transition: border-color 0.15s;
}
.oracle-textarea:focus { border-color: rgba(159,232,115,0.4); }
.oracle-textarea::placeholder { color: var(--text-dim); opacity: 0.5; }

.oracle-model-select {
  background: rgba(255,255,255,0.03);
  border: 1px solid rgba(159,232,115,0.12);
  color: var(--text-dim);
  font-family: inherit;
  font-size: 10px;
  padding: 4px 6px;
  outline: none;
  max-width: 120px;
  cursor: pointer;
}

.input-action {
  background: none;
  border: 1px solid rgba(159,232,115,0.15);
  color: var(--text-dim);
  cursor: pointer;
  font-family: inherit;
  font-size: 14px;
  width: 34px; height: 34px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 2px;
  transition: all 0.15s;
  flex-shrink: 0;
}
.input-action:hover { border-color: var(--cyan-glow); color: var(--cyan-glow); }
.input-plus  { font-size: 18px; color: var(--text-dim); }
.input-send  { color: var(--cyan-glow); border-color: rgba(159,232,115,0.3); }
.input-send:hover  { background: rgba(159,232,115,0.1); }
.input-send:disabled { opacity: 0.4; cursor: not-allowed; }
.input-mic   { color: var(--text-dim); }
.input-mic.active { color: var(--red-fusion); border-color: var(--red-fusion); animation: micPulse 1s ease-in-out infinite; }
@keyframes micPulse { 0%,100% { box-shadow: 0 0 0 0 rgba(217,112,72,0.4); } 50% { box-shadow: 0 0 0 6px rgba(217,112,72,0); } }

.reasoning-level {
  font-size: 9px;
  letter-spacing: 0.1em;
  font-weight: bold;
  width: 40px;
}

/* TERMINAL PANE */
.oracle-terminal-pane {
  border-top: 1px solid rgba(159,232,115,0.2);
  overflow: hidden;
  background: #0a0a0a;
}
`;

toolUseResult.content:
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    submitOracleCommandStream,
    submitOracleCommand,
    subscribeOracleCommandState,
    type OracleCommandState
} from '../../lib/oracleCommandBridge';
import { apiFetch } from '../../lib/runtime';
import VisualSynthesisLane from './VisualSynthesisLane';
import OracleToolOrbs from './OracleToolOrbs';
import OracleTerminal from './OracleTerminal';

interface ChatMessage {
    id: string;
    role: 'user' | 'nexus';
    content: string;
    streaming?: boolean;
    timestamp: string;
    files?: UploadedFile[];
}

interface UploadedFile {
    name: string;
    type: string;
    dataUrl: string;
    size: number;
}

interface ImageModel {
    id: string;
    label: string;
    provider: string;
}

type TabId = 'context' | 'research' | 'code' | 'visual' | 'ops';

const TABS: { id: TabId; label: string; icon: string }[] = [
    { id: 'context', label: 'Context',  icon: '◈' },
    { id: 'research', label: 'Research', icon: '◎' },
    { id: 'code',    label: 'Code',     icon: '⬡' },
    { id: 'visual',  label: 'Visual',   icon: '◆' },
    { id: 'ops',     label: 'Ops',      icon: '◉' }
];

const REASONING_LEVELS = ['low', 'medium', 'high', 'council'] as const;
type ReasoningLevel = typeof REASONING_LEVELS[number];

const REASONING_COLORS: Record<ReasoningLevel, string> = {
    low:     'var(--text-dim)',
    medium:  'var(--cyan-glow)',
    high:    'var(--gold-solar)',
    council: 'var(--red-fusion)'
};

export default function OraclePage() {
    const [messages, setMessages] = useState<ChatMessage[]>([{
        id: 'boot',
        role: 'nexus',
        content: 'NEXUS — Oracle online. All systems nominal. What directive shall I process?',
        timestamp: new Date().toISOString()
    }]);
    const [input, setInput]           = useState('');
    const [activeTab, setActiveTab]   = useState<TabId>('context');
    const [reasoning, setReasoning]   = useState<ReasoningLevel>('medium');
    const [terminalOpen, setTerminalOpen] = useState(false);
    const [dragOver, setDragOver]     = useState(false);
    const [pendingFiles, setPendingFiles] = useState<UploadedFile[]>([]);
    const [isListening, setIsListening] = useState(false);
    const [imageModels, setImageModels] = useState<{ kie: ImageModel[]; remote: ImageModel[] }>({ kie: [], remote: [] });
    const [oracleState, setOracleState] = useState<OracleCommandState | null>(null);
    const [models, setModels]          = useState<any[]>([]);
    const [selectedModel, setSelectedModel] = useState<string>('qwen-liberated:latest');

    const chatEndRef   = useRef<HTMLDivElement>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);
    const recognitionRef = useRef<SpeechRecognition | null>(null);

    // Subscribe to oracle state
    useEffect(() => {
        return subscribeOracleCommandState(setOracleState);
    }, []);

    // Auto-scroll chat
    useEffect(() => {
        chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [messages]);

    // Load models + image model catalog
    useEffect(() => {
        apiFetch('/api/neural/models').then(r => r.json()).then(setModels).catch(() => {});
        apiFetch('/api/neural/images/models').then(r => r.json()).then(setImageModels).catch(() => {});
    }, []);

    const addMessage = useCallback((msg: ChatMessage) => {
        setMessages(prev => [...prev, msg]);
    }, []);

    const updateLastNexus = useCallback((patch: Partial<ChatMessage>) => {
        setMessages(prev => {
            const idx = [...prev].reverse().findIndex(m => m.role === 'nexus');
            if (idx === -1) return prev;
            const realIdx = prev.length - 1 - idx;
            return prev.map((m, i) => i === realIdx ? { ...m, ...patch } : m);
        });
    }, []);

    const handleSubmit = useCallback(async () => {
        const cmd = input.trim();
        if (!cmd && pendingFiles.length === 0) return;
        setInput('');

        const userMsg: ChatMessage = {
            id: `u-${Date.now()}`,
            role: 'user',
            content: cmd || '[file upload]',
            timestamp: new Date().toISOString(),
            files: pendingFiles.length > 0 ? [...pendingFiles] : undefined
        };
        addMessage(userMsg);
        setPendingFiles([]);

        const nexusId = `n-${Date.now()}`;
        addMessage({ id: nexusId, role: 'nexus', content: '', streaming: true, timestamp: new Date().toISOString() });

        const useCouncil = reasoning === 'council';

        if (!useCouncil) {
            // Streaming path — near-realtime
            try {
                await submitOracleCommandStream({
                    command: cmd || 'describe uploaded files',
                    source: 'typed',
                    modelId: selectedModel,
                    onChunk: (chunk) => {
                        if (chunk.type === 'token') {
                            setMessages(prev => prev.map(m =>
                                m.id === nexusId
                                    ? { ...m, content: m.content + (chunk.token || ''), streaming: true }
                                    : m
                            ));
                        } else if (chunk.type === 'done') {
                            setMessages(prev => prev.map(m =>
                                m.id === nexusId
                                    ? { ...m, content: chunk.content || m.content, streaming: false }
                                    : m
                            ));
                        } else if (chunk.type === 'error') {
                            setMessages(prev => prev.map(m =>
                                m.id === nexusId
                                    ? { ...m, content: `[Oracle error: ${chunk.error}]`, streaming: false }
                                    : m
                            ));
                        }
                    }
                });
            } catch (err: any) {
                updateLastNexus({ content: `[Stream failed: ${err.message}]`, streaming: false });
            }
        } else {
            // Council mode — blocking with phase display
            try {
                const result = await submitOracleCommand({
                    command: cmd,
                    source: 'typed',
                    useCouncil: true
                });
                const content = result?.response || result?.content || JSON.stringify(result);
                updateLastNexus({ content: String(content), streaming: false });
            } catch (err: any) {
                updateLastNexus({ content: `[Council error: ${err.message}]`, streaming: false });
            }
        }
    }, [input, pendingFiles, reasoning, selectedModel, addMessage, updateLastNexus]);

    const handleKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSubmit(); }
    }, [handleSubmit]);

    const handleFileDrop = useCallback((files: FileList | null) => {
        if (!files) return;
        const allowed = ['application/pdf', 'image/png', 'image/jpeg', 'image/gif', 'image/webp',
            'text/markdown', 'text/plain', 'application/x-python', 'text/x-python'];
        Array.from(files).forEach(file => {
            if (!allowed.some(t => file.type === t || file.name.endsWith('.md') || file.name.endsWith('.py') || file.name.endsWith('.ts'))) return;
            const reader = new FileReader();
            reader.onload = () => {
                setPendingFiles(prev => [...prev, {
                    name: file.name,
                    type: file.type,
                    dataUrl: reader.result as string,
                    size: file.size
                }]);
            };
            reader.readAsDataURL(file);
        });
    }, []);

    const toggleVoice = useCallback(() => {
        const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SR) return;
        if (isListening) {
            recognitionRef.current?.stop();
            setIsListening(false);
            return;
        }
        const rec = new SR();
        rec.lang = 'en-US';
        rec.continuous = false;
        rec.onresult = (e: SpeechRecognitionEvent) => {
            const text = e.results[0]?.[0]?.transcript || '';
            setInput(prev => (prev + ' ' + text).trim());
            setIsListening(false);
        };
        rec.onend = () => setIsListening(false);
        rec.start();
        recognitionRef.current = rec;
        setIsListening(true);
    }, [isListening]);

    const cycleReasoning = useCallback(() => {
        setReasoning(prev => {
            const idx = REASONING_LEVELS.indexOf(prev);
            return REASONING_LEVELS[(idx + 1) % REASONING_LEVELS.length];
        });
    }, []);

    const isBusy = oracleState?.phase === 'submitted' || oracleState?.phase === 'deliberating';

    return (
        <div className="oracle-page" onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={e => { e.preventDefault(); setDragOver(false); handleFileDrop(e.dataTransfer.files); }}
        >
            {/* Drop overlay */}
            <AnimatePresence>
                {dragOver && (
                    <motion.div className="oracle-drop-overlay"
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>
                        <span>Drop files into NEXUS</span>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* Main layout */}
            <div className="oracle-layout">

                {/* LEFT — Category tabs */}
                <div className="oracle-tabs">
                    {TABS.map(tab => (
                        <button key={tab.id} className={`oracle-tab ${activeTab === tab.id ? 'active' : ''}`}
                            onClick={() => setActiveTab(tab.id)}>
                            <span className="tab-icon">{tab.icon}</span>
                            <span className="tab-label">{tab.label}</span>
                        </button>
                    ))}
                    <div className="oracle-tab-spacer"/>
                    <button className="oracle-tab terminal-toggle" onClick={() => setTerminalOpen(p => !p)}>
                        <span className="tab-icon">_</span>
                        <span className="tab-label">Terminal</span>
                    </button>
                </div>

                {/* CENTER — Chat + orbs */}
                <div className="oracle-center">

                    {/* Tool orbs or tab content */}
                    <div className="oracle-content-area">
                        {activeTab === 'visual' ? (
                            <VisualSynthesisLane models={imageModels} />
                        ) : (
                            <OracleToolOrbs activeTab={activeTab} />
                        )}
                    </div>

                    {/* Chat thread */}
                    <div className="oracle-chat">
                        <div className="oracle-messages">
                            {messages.map(msg => (
                                <motion.div key={msg.id} className={`oracle-msg oracle-msg--${msg.role}`}
                                    initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
                                    transition={{ duration: 0.2 }}>
                                    <span className="msg-label">
                                        {msg.role === 'user' ? 'NEXUS' : 'ORACLE'}
                                    </span>
                                    <div className="msg-body">
                                        {msg.content}
                                        {msg.streaming && <span className="cursor-blink">▋</span>}
                                    </div>
                                    {msg.files && msg.files.length > 0 && (
                                        <div className="msg-files">
                                            {msg.files.map((f, i) => (
                                                <span key={i} className="msg-file-pill">{f.name}</span>
                                            ))}
                                        </div>
                                    )}
                                </motion.div>
                            ))}
                            {isBusy && (
                                <div className="oracle-phase-indicator">
                                    <span className="phase-dot"/>
                                    {oracleState?.phase} · {oracleState?.elapsedMs ? Math.floor(oracleState.elapsedMs / 1000) + 's' : '...'}
                                </div>
                            )}
                            <div ref={chatEndRef}/>
                        </div>

                        {/* Pending file pills */}
                        {pendingFiles.length > 0 && (
                            <div className="oracle-pending-files">
                                {pendingFiles.map((f, i) => (
                                    <span key={i} className="pending-file-pill">
                                        {f.name}
                                        <button onClick={() => setPendingFiles(p => p.filter((_, j) => j !== i))}>×</button>
                                    </span>
                                ))}
                            </div>
                        )}

                        {/* Input bar */}
                        <div className="oracle-input-bar">
                            {/* Plus — file picker */}
                            <button className="input-action input-plus" onClick={() => fileInputRef.current?.click()} title="Attach file">
                                +
                            </button>
                            <input ref={fileInputRef} type="file" multiple hidden
                                accept=".pdf,.png,.jpg,.jpeg,.gif,.webp,.md,.py,.ts,.txt"
                                onChange={e => handleFileDrop(e.target.files)}/>

                            <textarea
                                className="oracle-textarea"
                                value={input}
                                onChange={e => setInput(e.target.value)}
                                onKeyDown={handleKeyDown}
                                placeholder="Ask NEXUS..."
                                rows={1}
                            />

                            {/* Model selector */}
                            <select className="oracle-model-select" value={selectedModel}
                                onChange={e => setSelectedModel(e.target.value)}>
                                {models.length > 0
                                    ? models.map((m: any) => <option key={m.id} value={m.id}>{m.name || m.id}</option>)
                                    : <option value="qwen-liberated:latest">Qwen Local</option>}
                            </select>

                            {/* Reasoning level */}
                            <button className="input-action reasoning-level"
                                style={{ color: REASONING_COLORS[reasoning] }}
                                onClick={cycleReasoning}
                                title={`Reasoning: ${reasoning}`}>
                                {reasoning.slice(0, 3).toUpperCase()}
                            </button>

                            {/* Mic */}
                            <button className={`input-action input-mic ${isListening ? 'active' : ''}`}
                                onClick={toggleVoice} title="Voice input">
                                {isListening ? '◉' : '🎤'}
                            </button>

                            {/* Send */}
                            <button className="input-action input-send" onClick={handleSubmit} disabled={isBusy}>
                                {isBusy ? '⟳' : '↑'}
                            </button>
                        </div>
                    </div>
                </div>
            </div>

            {/* Terminal pane (collapsible) */}
            <AnimatePresence>
                {terminalOpen && (
                    <motion.div className="oracle-terminal-pane"
                        initial={{ height: 0 }} animate={{ height: 320 }} exit={{ height: 0 }}
                        transition={{ duration: 0.25 }}>
                        <OracleTerminal />
                    </motion.div>
                )}
            </AnimatePresence>

            <style>{ORACLE_STYLES}</style>
        </div>
    );
}

const ORACLE_STYLES = `
