            try { (JSON.parse(r.topic_tags) as string[]).forEach(t => { tagFreq[t] = (tagFreq[t] || 0) + 1; }); } catch (_) {}
        });
        const topTopics = Object.entries(tagFreq).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([t]) => t);

