import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { apiFetch } from '../lib/runtime';
import { humanizeLabel } from '../lib/labels';

interface Ticket {
    id: number;
    external_id: string;
    title: string;
    status: string;
    priority: string;
    assigned_to: string;
    client: string;
}

